for(let axis=0;axis<hotspot.at.length;axis+=1){
const delta=(point[axis]??0)-hotspot.at[axis];
sum+=delta*delta;
}
const distance=Math.sqrt(sum);
if(distance<=hotspot.radius&&distance<bestDistance){
best=hotspot;
bestDistance=distance;
}
